import csv, os, io, contextlib
SC=os.environ["SC"]
# import data/helpers (suppress its verification prints)
with contextlib.redirect_stdout(io.StringIO()):
    from portfolio import DATA, wavg, totmv, N
TOTAL=156708098

FILLED={"VXUS","MU","AMD","MITTPRA","SCHD","LLY","PLTR","TECK","SLV","FNDX","VEON","SONY",
 "NVO","FER","MRVL","MCK","COPP","IVV","Q","MICC","SIVR","LEN","SLNAF","KYIV","941:HK",
 "NEAR","GOVT","JBND","SPIB","SPTL","IEF","EDV","LCPMX","SGOV","ICSH","NH"}
ANOM={"MU","AMD","MRVL"}
NADATA={"OXYWS","FCASH","968080101"}

BENCH={
 "S&P 500":[-0.95,15.20,10.21,22.32,20.61,13.41,15.49],
 "Russell 1000 Growth":[-2.68,16.74,5.33,17.71,22.58,13.71,18.55],
 "Russell 1000 Value":[2.27,13.87,16.26,27.12,17.79,11.17,11.52],
 "Russell 2000":[3.74,21.49,22.57,40.78,18.60,6.98,11.58],
 "MSCI ACWI ex US":[-0.59,14.49,13.68,27.66,18.82,8.79,9.85],
 "MSCI Emerging Markets":[-1.19,22.60,21.79,41.26,21.06,6.18,9.52],
 "Bloomberg US Agg Bond":[0.28,0.32,0.28,2.71,3.17,-0.42,0.84],
 "Blmbg 1-3 Mth T-Bill":[0.29,0.88,1.74,3.83,4.60,3.47,2.21],
 "Bloomberg US Corp HY":[0.27,2.47,1.96,5.91,8.86,4.17,5.77],
}
# render structure: (kind, payload)
SECT_EQ="PUBLIC EQUITY"; SECT_FI="FIXED INCOME"
PLAN=[
 ("section",SECT_EQ),
 ("sleeve","US Large Cap"),("subtotal","US Large Cap"),("bench",["S&P 500","Russell 1000 Growth","Russell 1000 Value"]),
 ("sleeve","US Small / Mid Cap"),("subtotal","US Small / Mid Cap"),("bench",["Russell 2000"]),
 ("sleeve","Developed Intl / Global"),("subtotal","Developed Intl / Global"),("bench",["MSCI ACWI ex US"]),
 ("sleeve","Emerging Markets"),("subtotal","Emerging Markets"),("bench",["MSCI Emerging Markets"]),
 ("sleeve","Regional / Sector Equity"),
 ("sleeve","Commodities"),("subtotal","Commodities"),
 ("sleeve","Digital Assets"),("subtotal","Digital Assets"),
 ("sleeve","Direct Equity"),("subtotal","Direct Equity"),("bench",["S&P 500","Russell 2000"]),
 ("sleeve","Other / Multi-Asset"),
 ("section",SECT_FI),
 ("sleeve","Multi-Sector Bond"),("subtotal","Multi-Sector Bond"),("bench",["Bloomberg US Agg Bond"]),
 ("sleeve","Short Duration"),("subtotal","Short Duration"),("bench",["Blmbg 1-3 Mth T-Bill"]),
 ("sleeve","Bank Loan / High Yield"),("subtotal","Bank Loan / High Yield"),("bench",["Bloomberg US Corp HY"]),
 ("sleeve","Core / Govt Bond ETFs"),("subtotal","Core / Govt Bond ETFs"),("bench",["Bloomberg US Agg Bond"]),
 ("sleeve","Money Market & Cash"),("subtotal","Money Market & Cash"),("bench",["Blmbg 1-3 Mth T-Bill"]),
 ("grandtotal",None),
]
EQ=[r for s in ["US Large Cap","US Small / Mid Cap","Developed Intl / Global","Emerging Markets",
 "Regional / Sector Equity","Commodities","Digital Assets","Direct Equity","Other / Multi-Asset"] for r in DATA[s]]
FI=[r for s in ["Multi-Sector Bond","Short Duration","Bank Loan / High Yield","Core / Govt Bond ETFs","Money Market & Cash"] for r in DATA[s]]
SUBLABEL={"Direct Equity":"Direct Equity subtotal ‡"}

def num(v): return "" if v is None else f"{v:.2f}"
def pct(mv): return f"{mv/TOTAL*100:.1f}%"

# ---------- CSV ----------
with open(os.path.join(SC,"completed_portfolio.csv"),"w",newline="") as fh:
    w=csv.writer(fh)
    w.writerow(["Row Type","Section","Sleeve","Holding","Ticker","Category","Market Value","% Port",
                "1 Mo","3 Mo","YTD","1 Yr","3 Yr","5 Yr","10 Yr","Note"])
    cursec=""
    for kind,pl in PLAN:
        if kind=="section": cursec=pl; w.writerow(["SECTION",pl,"","","","","","","","","","","","","",""]); continue
        if kind=="sleeve":
            w.writerow(["SLEEVE",cursec,pl,"","","","","","","","","","","","",""])
            for (tk,name,cat,mv,rets,ex) in DATA[pl]:
                note=[]
                if tk in ANOM: note.append("ANOMALY: Morningstar return index appears corrupted; do not trust")
                if tk=="941:HK": note.append("returns in HKD (local), not USD")
                if tk=="SLNAF": note.append("degenerate/delisted ~$0")
                if tk in NADATA: note.append("no Morningstar return security")
                if tk in FILLED and tk not in ANOM: note.append("newly filled from Morningstar Direct")
                w.writerow(["HOLDING",cursec,pl,name,tk,cat,mv,pct(mv),*[num(x) for x in rets],"; ".join(note)])
        elif kind=="subtotal":
            lab=SUBLABEL.get(pl,pl+" subtotal"); mv=totmv(DATA[pl])
            w.writerow(["SUBTOTAL",cursec,pl,lab,"","",mv,pct(mv),*[num(x) for x in wavg(DATA[pl])],""])
        elif kind=="bench":
            for b in pl: w.writerow(["BENCHMARK",cursec,"","vs. "+b,"","","","",*[num(x) for x in BENCH[b]],""])
        elif kind=="grandtotal":
            w.writerow(["TOTAL",SECT_FI,"","Total Equity & Real Assets","","",totmv(EQ),pct(totmv(EQ)),*[num(x) for x in wavg(EQ)],"recomputed; excludes corrupted MU/AMD/MRVL & no-data holdings"])
            w.writerow(["TOTAL","","","Total Fixed Income & Cash","","",totmv(FI),pct(totmv(FI)),*[num(x) for x in wavg(FI)],"recomputed"])
            w.writerow(["TOTAL","","","Total Public Markets","","",totmv(EQ+FI),"100.0%",*[num(x) for x in wavg(EQ+FI)],"recomputed"])
            w.writerow(["BENCHMARK","","","vs. S&P 500","","","","",*[num(x) for x in BENCH['S&P 500']],""])
            w.writerow(["BENCHMARK","","","vs. Bloomberg US Agg Bond","","","","",*[num(x) for x in BENCH['Bloomberg US Agg Bond']],""])
print("CSV written:", os.path.join(SC,"completed_portfolio.csv"))

# ---------- HTML ----------
COLNAMES=["1 Mo","3 Mo","YTD","1 Yr","3 Yr","5 Yr","10 Yr"]
def cell(v, anom=False):
    if v is None: return '<td class="n na">—</td>'
    neg = v<0
    txt = f"({abs(v):.2f})" if neg else f"{v:.2f}"
    cls="n"+(" neg" if neg else "")+(" anom" if anom else "")
    return f'<td class="{cls}">{txt}</td>'
def datacells(rets, anom=False): return "".join(cell(v,anom) for v in rets)

rows_html=[]
cursec=""
def money(mv): return f"${mv:,.0f}"
for kind,pl in PLAN:
    if kind=="section":
        cursec=pl
        rows_html.append(f'<tr class="sec"><td class="lbl" colspan="4">{pl}</td>'+''.join('<td></td>' for _ in range(7))+'</tr>')
        continue
    if kind=="sleeve":
        rows_html.append(f'<tr class="sleeve"><td class="lbl" colspan="4">{pl}</td>'+''.join('<td></td>' for _ in range(7))+'</tr>')
        for (tk,name,cat,mv,rets,ex) in DATA[pl]:
            anom = tk in ANOM
            flags=""
            if anom: flags='<span class="flag warn" title="Return index appears corrupted">⚠</span>'
            elif tk=="941:HK": flags='<span class="flag" title="Returns in HKD (local), not USD">†</span>'
            elif tk=="SLNAF": flags='<span class="flag" title="Delisted / ~$0">§</span>'
            elif tk in NADATA: flags='<span class="flag" title="No Morningstar return security">‖</span>'
            newcls=" new" if tk in FILLED else ""
            tkdisp = "" if tk in ("968080101",) else tk
            rows_html.append(
              f'<tr class="hold{newcls}">'
              f'<td class="name">{name}{flags}</td>'
              f'<td class="tk">{tkdisp}</td>'
              f'<td class="cat">{cat}</td>'
              f'<td class="n mv">{money(mv)}</td>'
              +datacells(rets,anom)+'</tr>')
    elif kind=="subtotal":
        lab=SUBLABEL.get(pl,pl+" subtotal"); mv=totmv(DATA[pl])
        rows_html.append(
          f'<tr class="sub"><td class="name">{lab}</td><td></td><td></td>'
          f'<td class="n mv">{money(mv)}</td>'+datacells(wavg(DATA[pl]))+'</tr>')
    elif kind=="bench":
        for b in pl:
            rows_html.append(f'<tr class="bench"><td class="name">vs. {b}</td><td></td><td></td><td></td>'+datacells(BENCH[b])+'</tr>')
    elif kind=="grandtotal":
        for lab,rows in [("Total Equity &amp; Real Assets",EQ),("Total Fixed Income &amp; Cash",FI),("Total Public Markets",EQ+FI)]:
            mv=totmv(rows)
            rows_html.append(f'<tr class="tot"><td class="name">{lab}</td><td></td><td></td><td class="n mv">{money(mv)}</td>'+datacells(wavg(rows))+'</tr>')
        rows_html.append(f'<tr class="bench"><td class="name">vs. S&amp;P 500</td><td></td><td></td><td></td>'+datacells(BENCH["S&P 500"])+'</tr>')
        rows_html.append(f'<tr class="bench"><td class="name">vs. Bloomberg US Agg Bond</td><td></td><td></td><td></td>'+datacells(BENCH["Bloomberg US Agg Bond"])+'</tr>')

thead='<tr><th class="name">Holding</th><th class="tk">Ticker</th><th class="cat">Category</th><th class="n">Market Value</th>'+''.join(f'<th class="n">{c}</th>' for c in COLNAMES)+'</tr>'

